import os,json,urllib.request,urllib.error,sys,re
from pathlib import Path
ROOT=Path(__file__).parent

def api(method,path,body=None,label=None):
 data=None if body is None else json.dumps(body).encode()
 req=urllib.request.Request(os.environ['MCPJAM_API_URL'].rstrip('/')+path,data=data,method=method,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'})
 try:
  with urllib.request.urlopen(req,timeout=25) as r: status=r.status; result=json.load(r)
 except urllib.error.HTTPError as e:
  status=e.code; result=json.loads(e.read())
 record={'method':method,'path':path,'status':status,'response':result}
 if label: (ROOT/(label+'.json')).write_text(json.dumps(record,indent=2))
 print(json.dumps(record));return status,result
if __name__=='__main__': api(sys.argv[1],sys.argv[2],json.loads(sys.argv[3]) if len(sys.argv)>3 else None,sys.argv[4] if len(sys.argv)>4 else 'last-response')
